package dev.sablelife.testing;
import dev.sablelife.SableLife;import dev.sablelife.heart.*;import dev.sablelife.module.*;import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;import dev.ryanhcode.sable.companion.math.BoundingBox3i;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.level.block.Blocks;import net.neoforged.neoforge.gametest.*;import java.util.*;
@GameTestHolder("sablelife_control_tests") @PrefixGameTestTemplate(false)
public final class HealthPhaseRuleGameTests {
 private static HeartBlockEntity core(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());for(int i=0;i<3;i++){c.wireless().add();c.wireless().channel(i).set(0,1);c.wireless().channel(i).set(6,3);}return c;}
 @GameTest(template="combat",batch="phase_rows_ranges") public static void OneModuleDrivesAdjacentStagesAndOverlappingOutputsUseMaximum(GameTestHelper h){var c=core(h);var m=c.modules().add("health_phase");var upper=m.healthPhaseRules().rows().getFirst();upper.edit("phaseLower",50);upper.edit("phaseChannel",1);upper.edit("phasePower",4);var lower=m.healthPhaseRules().add();lower.edit("phaseLower",0);lower.edit("phaseUpper",50);lower.edit("phaseChannel",2);var overlap=m.healthPhaseRules().add();overlap.edit("phaseLower",0);overlap.edit("phaseChannel",1);overlap.edit("phasePower",11);c.tryActivate(TestActors.creative(h.getLevel()));var runtime=new ModuleHealthPhase();runtime.tick(c);h.assertTrue(c.wireless().output(0)==11&&c.wireless().output(1)==0,"Overlap did not use maximum strength");c.damage(50);runtime.tick(c);h.assertTrue(c.wireless().output(1)==15&&runtime.snapshot(m.id()).getInt("ActiveCount")==2,"Exact threshold did not move to lower stage");overlap.edit("enabled",0);runtime.tick(c);h.assertTrue(c.wireless().output(0)==0&&c.wireless().output(1)==15,"Disabled overlap remained active");m.edit("trigger",2,"");m.edit("channel",3,"");runtime.tick(c);h.assertTrue(c.wireless().output(1)==0,"Outer gate ignored");h.succeed();}
 @GameTest(template="combat",batch="phase_rows_armor_link") public static void OnePhaseTableControlsArmorRowsAcrossHalfHealth(GameTestHelper h){var c=core(h);var stage=c.modules().add("health_phase");var high=stage.healthPhaseRules().rows().getFirst();high.edit("phaseLower",50);high.edit("phaseChannel",1);var low=stage.healthPhaseRules().add();low.edit("phaseLower",0);low.edit("phaseUpper",50);low.edit("phaseChannel",2);var armor=c.modules().add("armor");armor.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));var protect=armor.armorRules().add();protect.edit("channel",1);protect.edit("modifier",-100);var vulnerable=armor.armorRules().add();vulnerable.edit("channel",2);vulnerable.edit("modifier",50);c.tryActivate(TestActors.creative(h.getLevel()));var runtime=new ModuleHealthPhase();runtime.tick(c);h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==0,"High phase did not provide immunity");c.damage(60);runtime.tick(c);h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==30,"Low phase did not switch to vulnerability");h.succeed();}
 @GameTest(template="combat",batch="phase_rows_clocks") public static void PulseClocksStayIndependentAcrossEditsReorderAndHoldRows(GameTestHelper h){var c=core(h);var m=c.modules().add("health_phase");var p=m.healthPhaseRules().rows().getFirst();p.edit("phaseMode",1);p.edit("phasePulse",2);p.edit("phaseChannel",1);var hold=m.healthPhaseRules().add();hold.edit("phaseChannel",2);c.tryActivate(TestActors.creative(h.getLevel()));var runtime=new ModuleHealthPhase();runtime.tick(c);h.assertTrue(c.wireless().output(0)==15&&c.wireless().output(1)==15,"Initial rows did not activate");hold.edit("phasePower",5);m.healthPhaseRules().move(p.id(),1);runtime.tick(c);runtime.tick(c);h.assertTrue(c.wireless().output(0)==0&&c.wireless().output(1)==5,"Editing another row restarted pulse or stopped hold");c.damage(40);runtime.tick(c);c.restoreFullHealth();runtime.tick(c);h.assertTrue(c.wireless().output(0)==15,"Reentering failed to rearm pulse");p.edit("phaseUpper",60);p.edit("phaseLower",80);runtime.tick(c);h.assertTrue(c.wireless().output(0)==0,"Invalid band produced signal");runtime.clear();h.assertTrue(c.wireless().output(1)==0,"Runtime clear retained row output");h.succeed();}
 @GameTest(template="combat",batch="phase_rows_persistence") public static void RulesPersistBoundChannelsAndLegacySingleValuesBecomeFirstRow(GameTestHelper h){var m=new VirtualModule("health_phase");var a=m.healthPhaseRules().rows().getFirst();a.edit("phaseChannel",3);a.edit("phaseMode",1);a.edit("phasePulse",17);var b=m.healthPhaseRules().add();b.edit("phaseChannel",1);b.edit("phasePower",6);var saved=m.save();var load=VirtualModule.load(saved);h.assertTrue(load.healthPhaseRules().rows().size()==2&&load.healthPhaseRules().rows().getFirst().value("phasePulse")==17,"Rules failed save round trip");h.assertTrue(ModulePreset.create(saved).healthPhaseRules().rows().stream().allMatch(r->r.value("phaseChannel")==0),"Portable preset did not unbind channels");m.wirelessChannelDeleted(0);h.assertTrue(a.value("phaseChannel")==2&&b.value("phaseChannel")==0,"Channel deletion redirected rule");var legacy=new VirtualModule("health_phase").save();legacy.remove("HealthPhaseRules");var values=legacy.getCompound("Settings");values.putDouble("phaseLower",25);values.putDouble("phaseUpper",60);values.putDouble("phaseChannel",7);values.putDouble("phaseMode",1);values.putDouble("phasePulse",40);var migrated=VirtualModule.load(legacy).healthPhaseRules().rows();h.assertTrue(migrated.size()==1&&migrated.getFirst().value("phaseChannel")==7&&migrated.getFirst().value("phaseLower")==25&&migrated.getFirst().value("phasePulse")==40,"Old settings were lost");h.succeed();}
 @GameTest(template="combat",batch="phase_rows_limits") public static void RowBoundsInvalidDataAndEmptyListAreSafe(GameTestHelper h){var m=new VirtualModule("health_phase");var r=m.healthPhaseRules().rows().getFirst();h.assertTrue(!r.edit("phaseUpper",Double.NaN)&&!r.edit("phaseMode",2)&&!r.edit("phaseChannel",1.5)&&!r.edit("phasePower",16)&&!r.edit("phasePulse",0),"Unsafe row accepted");for(int i=1;i<64;i++)m.healthPhaseRules().add();h.assertTrue(m.healthPhaseRules().add()==null,"Too many rows accepted");var tag=m.save();tag.getList("HealthPhaseRules",10).getCompound(0).getCompound("Values").putDouble("phaseUpper",Double.NaN);h.assertTrue(VirtualModule.load(tag).healthPhaseRules().rows().size()==63,"Malformed row accepted");var empty=new VirtualModule("health_phase");empty.healthPhaseRules().remove(empty.healthPhaseRules().rows().getFirst().id());h.assertTrue(VirtualModule.load(empty.save()).healthPhaseRules().rows().isEmpty(),"Empty list restored a default row");h.succeed();}
 @GameTest(template="combat",batch="phase_rows_menu") public static void EditorRejectsStaleRevisionForeignRowAndActiveEditing(GameTestHelper h){var c=core(h);var m=c.modules().add("health_phase");var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var menu=new HealthPhaseRuleMenu(2,p.getInventory(),c,m,null);var r=m.healthPhaseRules().rows().getFirst();int v=c.modules().revision();h.assertTrue(!menu.action(p,v-1,r.id(),"phasePower",3)&&!menu.action(p,v,UUID.randomUUID(),"phasePower",3)&&!menu.action(p,v,r.id(),"phaseChannel",Double.NaN),"Invalid edit accepted");h.assertTrue(menu.action(p,v,r.id(),"phasePower",3),"Valid row edit rejected");c.tryActivate(p);h.assertTrue(!menu.action(p,c.modules().revision(),r.id(),"phasePower",8),"Alive read-only editor changed config");h.succeed();}
}
